"""Write web/handoff.html (the overnight handoff) and a plain HTML copy for Google Docs. Usage: build_handoff_page.py <stories.json> <out doc html>"""
import sys, json, html, os
R = json.load(open(sys.argv[1])); web = os.path.join(os.path.dirname(__file__), '..', 'web'); e = html.escape; BASE = 'https://francolinx.github.io/worn-smart-glasses/'
ok = sum(r['ok'] for r in R); frames = sum(len([f for f in r['frames'] if f.get('img')]) for r in R); fixes = sum(r['photo_fixes'] for r in R); shots = sum(r['shots'] for r in R); metres = sum(r['metres'] for r in R)
score = [('Scenarios passed (11 stories, floors 1 to 8)', f'{ok} / {len(R)}'), ('Glasses frames captured (every fix, turn, door, stair, arrival)', str(frames)), ('Real photo fixes inside the stories / photos taken', f'{fixes} / {shots}'),
 ('50 photo missions on floor 1', '48 / 50 reached the target, 0 wrong-place fixes'), ('30 upper-floor routing trials', '30 / 30 after one fix (28 / 30 before)'), ('Photo-to-photo test (71 survey photos)', '57 matched, all to the right or adjacent station')]
fixed = [('Router took the elevator when the target was an elevator lobby on another floor', 'Stairs and doors only. Elevators are never a connector.'),
 ('No route from Room A 105 to an upper floor (two plans apart)', 'Two-hop routing: room, then floor 1, then the stair.'), ('Stair E was missing from the floor-1 venue plan', 'Added where the EXIT STAIR E sign is in the photos.'),
 ('A code comment had swallowed the line that handles "the target is itself a stair"; scenario 2 crashed on it', 'Line restored; all 11 scenarios rerun.'), ('Weak photo matches were accepted and gave 3 wrong-place fixes in 50', 'Low-confidence matches are refused: "look another way".'),
 ('Glasses map was a list of words', 'Heading-up schematic: walls, green route, red exits and stairs, amber target, one big next move.'), ('Upper floors had no shapes at all', 'Floor outlines, stair cores and elevator cars traced from the fire signs.'),
 ('Stair names lower-cased, exit names cut off, no arrival or stair cue on the glasses', 'Fixed; "TAKE STAIR E TO FLOOR 8" and "ARRIVED" banners added.'), ('Upper-floor plans did not sit over each other', 'Refitted so shared stairs line up with floor 1, within 3.3 m.')]
todo = [('Maahi', 'Round-2 photos: 7 spots and 6 shots with the Meta glasses. Shot list is in the Drive folder.'), ('Franco', 'Run 3 or 4 real glasses photos through the app. Nothing has been matched from the glasses camera yet.'),
 ('Anyone', 'If we want floor 8 in the demo: 8 photos at the 8th-floor elevator lobby and 8 at the top of Stair E, same method.'), ('Rachel', 'MicroLumin M6: one-time Developer Mode and Wi-Fi join needs the iOS MLDemo build from a Mac. The glasses page is plain HTML, 600 by 600.'),
 ('Team', 'Pitch line: the phone compass was 35 to 50 degrees wrong in this corridor. We fix position and heading from one photo instead.')]
limits = ['Floors 2 to 8 have plans but no survey photos. Every position there is injected, not measured.', 'Frames marked "at the turn" are simulated positions. The real system only knows where you are when you take a photo.',
 'The fire signs do not name rooms, so upper floors show shapes, stairs, elevators and exits only.', 'All photo tests use the survey phone on the survey evening. The glasses camera, smoke and darkness are untested.',
 'Storey heights in the 3D view are assumed. Corridor metres do not include the stair climb.', 'Unit names and incidents in the stories are invented for the demo.']
def page(doc):
    img = lambda f, w=None: f'<img src="{(BASE if doc else "")}{f}"' + (f' width="{w}"' if doc else ' loading="lazy"') + '>'
    hl = lambda t: f'<span style="background-color:#ffff00"><b>{t}</b></span>' if doc else f'<mark>{t}</mark>'
    s = f"<h1>Point &amp; Go: overnight handoff</h1><p>Sat 21 Nov 2026, about 3 AM. Code freeze 2:00 PM, demos 2:15 PM. Everything below is live and in the repo.</p>"
    s += f"<p>{hl('Where we are: one photo gives a responder their floor, position and heading inside 285 Jay St, and the glasses show a floor schematic with the route. It works on our own phone photos of floor 1. It has not been tried with a photo from the glasses.')}</p>"
    s += '<h2>Open these</h2><ul>' + ''.join(f'<li><a href="{BASE}{u}">{t}</a></li>' for u, t in [('indoor.html', 'Phone app'), ('glasses.html', 'Glasses page (add it as a web app on the Meta glasses)'), ('building3d.html', 'Whole building in 3D: press Scenarios'), ('floor3d.html', 'Floor 1 in 3D with the survey photos'), ('benchmark.html', '50 photo missions, with the wearer\'s view'), ('handoff.html', 'This report as a web page')]) + '</ul>'
    s += '<h2>Scoreboard</h2><table border="1" cellpadding="6" style="border-collapse:collapse">' + ''.join(f'<tr><td>{e(a)}</td><td><b>{e(b)}</b></td></tr>' for a, b in score) + '</table>'
    s += f"<h2>The building</h2><p>{img('handoff/bird.png', 620)}</p><p>285 Jay St on satellite imagery, with the eight fire-plan floors stacked inside the footprint. The welcome packet confirms the building; it only covers the ground and second floors, so floors 3 to 8 come from the elevator fire signs.</p>"
    r = R[0]; s += f"<h2>Main scenario: {e(r['title'])}</h2><p><b>{e(r['persona'])} · {e(r['unit'])}.</b> {e(r['story'])}</p>"
    s += '<ol><li><b>Main entrance to Room A 105.</b> Photo fix at the information desk, corridor, through the north door, photo fix inside, to the front of the room. Nobody there.</li><li><b>A 105 to the 8th-floor elevators.</b> Photo fix in the room, out the north door, photo fix in the corridor, 3 m to Stair E, up seven storeys, then 25 m across floor 8 to the elevator lobby. No elevator at any point.</li><li><b>Out.</b> Back to Stair E, down to floor 1, 8 m to the Jay St exit.</li></ol>'
    s += f"<p>{img('handoff/s00_side.jpg', 620)}</p><p>{img('handoff/s00_board.jpg', 620)}</p><p>Every frame is what the glasses show at that moment. Green label: a real photo fix. Amber: position set by hand because that floor has no photos. Blue: simulated position at a turn.</p>"
    s += '<h2>Ten more scenarios</h2>'
    for r in R[1:]:
        s += f"<h3>{e(r['persona'])}: {e(r['title'])} <small>({'PASS' if r['ok'] else 'FAIL'}, {r['metres']} m)</small></h3><p><b>{e(r['unit'])}.</b> {e(r['story'])}</p><p>{img('handoff/' + r['id'] + '_stack.jpg', 520)}</p><p>{img('handoff/' + r['id'] + '_board.jpg', 620)}</p>"
        if r['errors']: s += '<p>' + e('; '.join(r['errors'])) + '</p>'
    s += '<h2>Errors found overnight and what was done</h2><table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Found</th><th>Fix</th></tr>' + ''.join(f'<tr><td>{e(a)}</td><td>{e(b)}</td></tr>' for a, b in fixed) + '</table>'
    s += f"<h2>Floor 1 with real photos</h2><p>{img('handoff/flow_floor1.png', 620)}</p>"
    s += '<h2>To do before 2 PM</h2><table border="1" cellpadding="6" style="border-collapse:collapse">' + ''.join(f'<tr><td>{hl(e(a))}</td><td>{e(b)}</td></tr>' for a, b in todo) + '</table>'
    s += '<h2>What is not proven</h2><ul>' + ''.join(f'<li>{e(x)}</li>' for x in limits) + '</ul>'
    s += '<p>Repo: https://github.com/francolinx/worn-smart-glasses · tools/run_stories.py, tools/bench_missions.py, tools/bench_vertical.py reproduce every number here.</p>'
    return s
open(web + '/handoff.html', 'w').write('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Point & Go · overnight handoff</title><style>body{background:#0e1116;color:#e6e8eb;font:16px/1.5 system-ui,-apple-system,sans-serif;max-width:900px;margin:auto;padding:14px}a{color:#ffb020}h1{font-size:26px}h2{margin-top:34px;border-top:1px solid #2a313b;padding-top:18px;color:#ffd27a}h3{color:#8fdcff;margin-top:26px}img{max-width:100%;border-radius:10px;border:1px solid #2a313b}table{width:100%}td,th{border-color:#2a313b!important;vertical-align:top}mark{background:#ffe600;color:#000;padding:1px 4px;border-radius:3px;font-weight:700}small{color:#9aa3ad;font-weight:400}</style></head><body>' + page(False) + '</body></html>')
open(sys.argv[2], 'w').write('<html><body>' + page(True) + '</body></html>'); print(len(page(True)), score)
